I'll implement the longest substring without repeating characters using a sliding window approach in O(n) time complexity.

```js
function longestSubstring(s) {
    if (s.length === 0) return 0;

    let charSet = new Set();
    let maxLength = 0;
    let left = 0;

    for (let right = 0; right < s.length; right++) {
        while (charSet.has(s[right])) {
            charSet.delete(s[left]);
            left++;
        }
        charSet.add(s[right]);
        maxLength = Math.max(maxLength, right - left + 1);
    }

    return maxLength;
}
```

