function countGraphemes(str) {
    if (!Intl.Segmenter) return str.length; // Fallback
    const segmenter = new Intl.Segmenter(undefined, { granularity: 'grapheme' });
    return [...segmenter.segment(str)].length;
}

function longestSubstringGraphemes(s) {
    if (s.length === 0) return 0;

    const graphemes = [...new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(s)];
    let maxLength = 0;
    let left = 0;
    const graphemeSet = new Set();

    for (let right = 0; right < graphemes.length; right++) {
        const currentGrapheme = graphemes[right].segment;
        while (graphemeSet.has(currentGrapheme)) {
            graphemeSet.delete(graphemes[left].segment);
            left++;
        }
        graphemeSet.add(currentGrapheme);
        maxLength = Math.max(maxLength, right - left + 1);
    }

    return maxLength;
}
```

2. **Runtime Support Policy**:
   - Intl.Segmenter is supported in modern browsers (Chrome 87+, Edge 87+, Safari 14.1+)
   - For Node.js: v16+ (with experimental flag in v16, stable in v17+)
   - Fallback to code point counting for older environments

### Why Length Measurements Must Be Consistent

When comparing brute-force and optimized implementations:

1. **Fair Comparison**: Both must measure the same unit to have a meaningful comparison of time complexity
2. **Correctness**: The optimized solution might accidentally work with code points but fail with grapheme clusters
3. **Consistency**: If brute-force measures grapheme clusters but optimized measures code points, the optimized solution might appear faster but actually be incorrect

For example, a brute-force solution checking all substrings of "👨‍👩‍👧‍👦a" would correctly identify 2 as the longest length (treating the emoji as one unit), while an optimized solution using UTF-16 code units might incorrectly calculate a different length.

