```js
/**
 * Checks if the brackets in a string are properly balanced and nested.
 * Non-bracket characters are ignored. Only considers '()', '[]', and '{}'.
 * @param {string} s - The input string to check
 * @returns {boolean} - True if all brackets are properly balanced, false otherwise
 */
function isValidBrackets(s) {
  // Handle invalid input types
  if (typeof s !== 'string') {
    return false;
  }

  const stack = [];
  const bracketPairs = {
    '(': ')',
    '[': ']',
    '{': '}'
  };

  for (let char of s) {
    // If it's an opening bracket, push to stack
    if (bracketPairs.hasOwnProperty(char)) {
      stack.push(char);
    } 
    // If it's a closing bracket
    else if (char === ')' || char === ']' || char === '}') {
      // If stack is empty, there's no matching opening bracket
      if (stack.length === 0) {
        return false;
      }

      // Pop the last opening bracket from stack
      const lastOpening = stack.pop();

      // Check if it matches the current closing bracket
      if (bracketPairs[lastOpening] !== char) {
        return false;
      }
    }
    // Non-bracket characters are ignored
  }

  // If stack is not empty, some brackets were not closed
  return stack.length === 0;
}
```

